example.org:53 {
    file /etc/coredns/example.org.db
    dnssec {
        key file /etc/coredns/Kexample.org.+013+12345
    }
}

.:53 {
    forward . tls://1.1.1.1 tls://1.0.0.1 {
        tls_servername cloudflare-dns.com
        health_check 5s
    }
    cache 30
}

ingress:
- from:
  - namespaceSelector:
      matchLabels: { team: a }
    podSelector:
      matchLabels: { role: client }

egress:
- to:
  - namespaceSelector:
      matchLabels: { kubernetes.io/metadata.name: kube-system }
    podSelector:
      matchLabels: { k8s-app: kube-dns }
  ports:
  - { protocol: UDP, port: 53 }
  - { protocol: TCP, port: 53 }
- to:
  - podSelector:
      matchLabels: { app: db }
  ports:
  - { protocol: TCP, port: 5432 }

